-- 461_intake_xjz_god_system_csharp_evidence.sql
-- Purpose: ingest C# restored god templates, visuals, acquisition rules, and capture routes without raw JSON exposure.
-- Source pack: XJZ-csharp-evidence-capture-pack-20260818.zip

DROP TABLE IF EXISTS god2_research._xjz_stage_god_template;
DROP TABLE IF EXISTS god2_research._xjz_stage_god_visual;
DROP TABLE IF EXISTS god2_research._xjz_stage_god_acquisition_rule;
DROP TABLE IF EXISTS god2_research._xjz_stage_god_acquisition_capture_target;
DROP TABLE IF EXISTS god2_research._xjz_stage_god_acquisition_playbook_route;
DROP TABLE IF EXISTS god2_research._xjz_stage_god_service_template;

CREATE TABLE god2_research._xjz_stage_god_template (god_template_id INT PRIMARY KEY, menu_category_id INT NOT NULL, protocol_id INT NOT NULL, name_zh_tw VARCHAR(160) NOT NULL, element_zh_tw VARCHAR(32) NOT NULL, level INT NOT NULL, vitality INT NOT NULL, strength INT NOT NULL, intelligence INT NOT NULL, speed INT NOT NULL, description_zh_tw TEXT NULL, raw_source VARCHAR(255) NOT NULL, raw_line INT NULL, evidence_status VARCHAR(96) NOT NULL, packet_evidence_boundary INT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE god2_research._xjz_stage_god_visual (visual_id INT PRIMARY KEY, visual_group VARCHAR(96) NOT NULL, role_code VARCHAR(64) NOT NULL, action_code VARCHAR(64) NOT NULL, file_identifier INT NOT NULL, rom_path VARCHAR(255) NOT NULL, palette_range VARCHAR(64) NULL, attack_action INT NULL, note_zh_tw TEXT NULL, part_category_zh_tw VARCHAR(128) NULL, raw_source VARCHAR(255) NOT NULL, raw_line INT NULL, evidence_status VARCHAR(96) NOT NULL, packet_evidence_boundary INT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE god2_research._xjz_stage_god_acquisition_rule (id INT PRIMARY KEY, quest_id INT NULL, god_template_id INT NULL, god_name_zh_tw VARCHAR(160) NULL, start_npc_id INT NULL, param_json LONGTEXT NOT NULL, packet_evidence_boundary INT NOT NULL, raw_source VARCHAR(255) NOT NULL, raw_line INT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE god2_research._xjz_stage_god_acquisition_capture_target (target_id INT PRIMARY KEY, rule_id INT NOT NULL, quest_id INT NULL, quest_code VARCHAR(96) NULL, quest_name_zh_tw VARCHAR(255) NULL, god_template_id INT NULL, god_name_zh_tw VARCHAR(160) NULL, start_npc_id INT NULL, static_binding_state VARCHAR(96) NOT NULL, capture_priority VARCHAR(32) NOT NULL, capture_context VARCHAR(128) NOT NULL, wanted_fields_json LONGTEXT NOT NULL, target_rule_table VARCHAR(128) NOT NULL, sample_table VARCHAR(128) NOT NULL, request_hint_zh_tw TEXT NOT NULL, current_client_source TEXT NOT NULL, raw_source VARCHAR(255) NOT NULL, raw_line INT NULL, evidence_status VARCHAR(96) NOT NULL, packet_evidence_boundary INT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE god2_research._xjz_stage_god_acquisition_playbook_route (route_binding_id INT PRIMARY KEY, target_id INT NOT NULL, rule_id INT NOT NULL, step_id INT NOT NULL, action_key VARCHAR(96) NOT NULL, quest_id INT NULL, quest_code VARCHAR(96) NULL, quest_name_zh_tw VARCHAR(255) NULL, god_template_id INT NULL, god_name_zh_tw VARCHAR(160) NULL, start_npc_id INT NULL, static_binding_state VARCHAR(96) NOT NULL, capture_priority VARCHAR(32) NOT NULL, capture_context VARCHAR(128) NOT NULL, target_rule_table VARCHAR(128) NOT NULL, sample_table VARCHAR(128) NOT NULL, route_id INT NOT NULL, query_id INT NOT NULL, required_run_key VARCHAR(96) NOT NULL, sample_count_sql TEXT NOT NULL, last_sample_id_sql TEXT NULL, presence_sql TEXT NOT NULL, route_state VARCHAR(64) NOT NULL, evidence_status VARCHAR(96) NOT NULL, packet_evidence_boundary INT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE god2_research._xjz_stage_god_service_template (service_id INT PRIMARY KEY, god_template_id INT NOT NULL, menu_category_id INT NOT NULL, protocol_id INT NOT NULL, name_zh_tw VARCHAR(160) NOT NULL, element_zh_tw VARCHAR(32) NOT NULL, level INT NOT NULL, vitality INT NOT NULL, strength INT NOT NULL, intelligence INT NOT NULL, speed INT NOT NULL, stat_total INT NOT NULL, base_stat_json LONGTEXT NOT NULL, description_zh_tw TEXT NULL, raw_source VARCHAR(255) NOT NULL, raw_line INT NULL, evidence_status VARCHAR(96) NOT NULL, packet_evidence_boundary INT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS god2_research.xjz_god_templates_evidence (
  god_template_id INT NOT NULL,
  menu_category_id INT NOT NULL,
  protocol_id INT NOT NULL,
  name_zh_tw VARCHAR(160) NOT NULL,
  element_zh_tw VARCHAR(32) NOT NULL,
  level INT NOT NULL,
  vitality INT NOT NULL,
  strength INT NOT NULL,
  intelligence INT NOT NULL,
  speed INT NOT NULL,
  stat_total INT NOT NULL,
  description_zh_tw TEXT NULL,
  source_line INT NULL,
  evidence_status_zh_tw VARCHAR(96) NOT NULL,
  needs_packet_evidence INT NOT NULL,
  PRIMARY KEY (god_template_id),
  UNIQUE KEY ux_xjz_god_protocol_name (protocol_id, name_zh_tw)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='C#證據包：神仙模板與基礎顯示能力。';

CREATE TABLE IF NOT EXISTS god2_research.xjz_god_visual_evidence (
  visual_id INT NOT NULL,
  visual_group_zh_tw VARCHAR(96) NOT NULL,
  role_code_zh_tw VARCHAR(64) NOT NULL,
  action_code_zh_tw VARCHAR(64) NOT NULL,
  file_identifier INT NOT NULL,
  rom_path_zh_tw VARCHAR(255) NOT NULL,
  palette_range_zh_tw VARCHAR(64) NULL,
  attack_action INT NULL,
  note_zh_tw TEXT NULL,
  part_category_zh_tw VARCHAR(128) NULL,
  source_line INT NULL,
  evidence_status_zh_tw VARCHAR(96) NOT NULL,
  needs_packet_evidence INT NOT NULL,
  PRIMARY KEY (visual_id),
  KEY ix_xjz_god_visual_group (visual_group_zh_tw)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='C#證據包：神仙外觀ROM與動作資源候選。';

CREATE TABLE IF NOT EXISTS god2_research.xjz_god_acquisition_rules_evidence (
  rule_id INT NOT NULL,
  quest_id INT NULL,
  god_template_id INT NULL,
  god_name_zh_tw VARCHAR(160) NULL,
  start_npc_id INT NULL,
  quest_name_zh_tw VARCHAR(255) NULL,
  quest_type_zh_tw VARCHAR(96) NULL,
  association_kind_zh_tw VARCHAR(128) NULL,
  min_rebirth INT NULL,
  min_level INT NULL,
  source_line INT NULL,
  needs_packet_evidence INT NOT NULL,
  PRIMARY KEY (rule_id),
  KEY ix_xjz_god_acquisition_quest (quest_id),
  KEY ix_xjz_god_acquisition_god (god_template_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='C#證據包：神仙取得規則候選。';

CREATE TABLE IF NOT EXISTS god2_research.xjz_god_acquisition_capture_targets (
  target_id INT NOT NULL,
  rule_id INT NOT NULL,
  quest_id INT NULL,
  quest_code_zh_tw VARCHAR(96) NULL,
  quest_name_zh_tw VARCHAR(255) NULL,
  god_template_id INT NULL,
  god_name_zh_tw VARCHAR(160) NULL,
  start_npc_id INT NULL,
  static_binding_state_zh_tw VARCHAR(128) NOT NULL,
  capture_priority_zh_tw VARCHAR(32) NOT NULL,
  capture_context_zh_tw VARCHAR(128) NOT NULL,
  wanted_fields_zh_tw TEXT NOT NULL,
  target_rule_table_zh_tw VARCHAR(128) NOT NULL,
  sample_table_zh_tw VARCHAR(128) NOT NULL,
  request_hint_zh_tw TEXT NOT NULL,
  source_line INT NULL,
  evidence_status_zh_tw VARCHAR(96) NOT NULL,
  needs_packet_evidence INT NOT NULL,
  PRIMARY KEY (target_id),
  KEY ix_xjz_god_capture_quest (quest_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='C#證據包：神仙取得抓包目標。';

CREATE TABLE IF NOT EXISTS god2_research.xjz_god_acquisition_playbook_routes (
  route_binding_id INT NOT NULL,
  target_id INT NOT NULL,
  rule_id INT NOT NULL,
  step_id INT NOT NULL,
  action_key_zh_tw VARCHAR(128) NOT NULL,
  quest_id INT NULL,
  quest_code_zh_tw VARCHAR(96) NULL,
  quest_name_zh_tw VARCHAR(255) NULL,
  god_template_id INT NULL,
  god_name_zh_tw VARCHAR(160) NULL,
  start_npc_id INT NULL,
  capture_priority_zh_tw VARCHAR(32) NOT NULL,
  capture_context_zh_tw VARCHAR(128) NOT NULL,
  target_rule_table_zh_tw VARCHAR(128) NOT NULL,
  sample_table_zh_tw VARCHAR(128) NOT NULL,
  route_id INT NOT NULL,
  query_id INT NOT NULL,
  route_state_zh_tw VARCHAR(64) NOT NULL,
  evidence_status_zh_tw VARCHAR(96) NOT NULL,
  needs_packet_evidence INT NOT NULL,
  PRIMARY KEY (route_binding_id),
  UNIQUE KEY ux_xjz_god_route (target_id, route_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='C#證據包：神仙取得抓包 playbook 路線。';

DELETE FROM god2_research.xjz_god_templates_evidence;
SELECT god_template_id, menu_category_id, protocol_id, name_zh_tw, element_zh_tw, level, vitality, strength, intelligence, speed, stat_total, description_zh_tw, raw_line, evidence_status, packet_evidence_boundary
FROM god2_research._xjz_stage_god_service_template;

DELETE FROM god2_research.xjz_god_visual_evidence;
SELECT visual_id, CASE visual_group WHEN 'god_doll' THEN '神仙一般外觀' ELSE visual_group END, role_code, action_code, file_identifier, rom_path, palette_range, attack_action, note_zh_tw, part_category_zh_tw, raw_line, evidence_status, packet_evidence_boundary
FROM god2_research._xjz_stage_god_visual;

DELETE FROM god2_research.xjz_god_acquisition_rules_evidence;
SELECT id, quest_id, god_template_id, god_name_zh_tw, start_npc_id, JSON_UNQUOTE(JSON_EXTRACT(param_json, '$.quest_name_zh_tw')), JSON_UNQUOTE(JSON_EXTRACT(param_json, '$.quest_type')), JSON_UNQUOTE(JSON_EXTRACT(param_json, '$.association_kind')), CAST(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(param_json, '$.min_rebirth')), 'null') AS SIGNED), CAST(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(param_json, '$.min_level')), 'null') AS SIGNED), raw_line, packet_evidence_boundary
FROM god2_research._xjz_stage_god_acquisition_rule;

DELETE FROM god2_research.xjz_god_acquisition_capture_targets;
SELECT target_id, rule_id, quest_id, quest_code, quest_name_zh_tw, god_template_id, god_name_zh_tw, start_npc_id, CASE static_binding_state WHEN 'needs_official_god_binding' THEN '需要官方取得綁定' ELSE static_binding_state END, CASE capture_priority WHEN 'high' THEN '高' ELSE capture_priority END, capture_context, REPLACE(REPLACE(REPLACE(REPLACE(wanted_fields_json, '"quest_id"', '任務ID'), '"god_template_id"', '神仙模板ID'), '"god_name_zh_tw"', '神仙名稱'), '"raw_packet_json"', '原始封包'), target_rule_table, sample_table, request_hint_zh_tw, raw_line, evidence_status, packet_evidence_boundary
FROM god2_research._xjz_stage_god_acquisition_capture_target;

DELETE FROM god2_research.xjz_god_acquisition_playbook_routes;
SELECT route_binding_id, target_id, rule_id, step_id, CASE action_key WHEN 'god_acquisition_flow' THEN '神仙取得流程' ELSE action_key END, quest_id, quest_code, quest_name_zh_tw, god_template_id, god_name_zh_tw, start_npc_id, CASE capture_priority WHEN 'high' THEN '高' ELSE capture_priority END, capture_context, target_rule_table, sample_table, route_id, query_id, CASE route_state WHEN 'enabled' THEN '啟用' ELSE route_state END, evidence_status, packet_evidence_boundary
FROM god2_research._xjz_stage_god_acquisition_playbook_route;

CREATE OR REPLACE VIEW god2_research.vw_xjz_god_system_csharp_summary_zh_tw AS
SELECT '神仙模板' AS 資料類型, COUNT(*) AS 筆數, SUM(needs_packet_evidence) AS 需要封包證據, NULL AS 高優先目標, '神仙選單、五行、基礎顯示能力' AS 遊戲功能
FROM god2_research.xjz_god_templates_evidence
UNION ALL
SELECT '神仙外觀資源', COUNT(*), SUM(needs_packet_evidence), NULL, '神仙外觀ROM與動作資源'
FROM god2_research.xjz_god_visual_evidence
UNION ALL
SELECT '神仙取得規則候選', COUNT(*), SUM(needs_packet_evidence), NULL, '任務與神仙取得關聯候選'
FROM god2_research.xjz_god_acquisition_rules_evidence
UNION ALL
SELECT '神仙取得抓包目標', COUNT(*), SUM(needs_packet_evidence), SUM(CASE WHEN capture_priority_zh_tw='高' THEN 1 ELSE 0 END), '實測取得神仙、任務、NPC、前後狀態'
FROM god2_research.xjz_god_acquisition_capture_targets
UNION ALL
SELECT '神仙取得Playbook路線', COUNT(*), SUM(needs_packet_evidence), NULL, '正式抓包流程路線'
FROM god2_research.xjz_god_acquisition_playbook_routes;

CREATE OR REPLACE VIEW god2_research.vw_xjz_god_system_text_quality_zh_tw AS
SELECT '神仙模板' AS 資料表, COUNT(*) AS 疑似亂碼或簡體殘留
FROM god2_research.xjz_god_templates_evidence
WHERE CONCAT_WS('', name_zh_tw, description_zh_tw) REGEXP '[�锛绔閵鐧傚偡绁炰粰国庆黄欢类卖贩们圆质给]'
UNION ALL
SELECT '神仙取得抓包目標', COUNT(*)
FROM god2_research.xjz_god_acquisition_capture_targets
WHERE CONCAT_WS('', quest_name_zh_tw, god_name_zh_tw, request_hint_zh_tw) REGEXP '[�锛绔閵鐧傚偡绁炰粰国庆黄欢类卖贩们圆质给]';

UPDATE god2_research.xjz_csharp_zip_evidence_digest
SET current_project_status_zh_tw = '已匯入神仙模板、外觀與取得流程候選',
    safe_apply_level_zh_tw = '可用於神仙資料對照與取得流程抓包；正式取得規則需官方樣本確認',
    next_server_action_zh_tw = '先比對正式神仙表與角色神仙狀態服務；神仙取得任務需跑官方抓包確認實際取得神仙、NPC與前後狀態。',
    blocked_reason_zh_tw = '模板資料可讀，但取得規則多為任務關聯候選；不得直接發放神仙。',
    related_project_object_zh_tw = 'migration 461, xjz_god_*'
WHERE evidence_key = 'god_system_sources';

